function ghostBody(cx, top, w, h) {
  const r = w / 2, pts = [];
  for (let i = 0; i <= 26; i++) { const t = Math.PI + i / 26 * Math.PI; pts.push([cx + r * Math.cos(t), top + r + r * 0.92 * Math.sin(t)]); }
  const bottomY = top + h, waves = 5, ww = w / waves;
  pts.push([cx + r, bottomY - 16]);
  for (let i = 0; i < waves; i++) {
    const xA = cx + r - ww * i, xB = xA - ww;
    for (let s = 1; s <= 8; s++) { const t = s / 8; pts.push([xA + (xB - xA) * t, bottomY - 16 + Math.sin(t * Math.PI) * 15]); }
  }
  pts.push([cx - r, top + r]);
  return pts;
}
